<?php
/** Run with wp eval-file on a disposable WordPress + Etch test site. */
if ( ! defined( 'ABSPATH' ) || ! function_exists( 'lfe_preview' ) ) { throw new Exception('Activate Looper on a disposable test site first.'); }
function lfe_security_check($ok,$label){if(!$ok)throw new Exception($label);echo 'PASS '.$label.PHP_EOL;}
function lfe_security_request($method,$path,$data=[]){$r=new WP_REST_Request($method,'/looper-for-etch/v1/'.$path);if($method==='POST'){$r->set_header('Content-Type','application/json');$r->set_body(wp_json_encode($data));}else foreach($data as$k=>$v)$r->set_param($k,$v);return rest_do_request($r);}
$old_user=get_current_user_id();$admins=get_users(['role'=>'administrator','number'=>1]);if(!$admins)throw new Exception('Administrator required.');$admin=$admins[0]->ID;$role='looper_audit_'.strtolower(wp_generate_password(6,false));$user=0;
try{
 wp_set_current_user(0);foreach(['content','loops','terms']as$path)lfe_security_check(lfe_security_request('GET',$path)->get_status()===401,'anonymous '.$path.' denied');lfe_security_check(lfe_security_request('POST','preview',['type'=>'wp-query','args'=>['post_type'=>'post']])->get_status()===401,'anonymous preview denied');
 add_role($role,'Temporary Looper audit',['read'=>true]);$user=wp_insert_user(['user_login'=>$role,'user_pass'=>wp_generate_password(32),'role'=>$role]);if(is_wp_error($user))throw new Exception('Temporary user creation failed');wp_set_current_user($user);lfe_security_check(lfe_security_request('GET','content')->get_status()===403,'low privilege discovery denied');lfe_security_check(lfe_security_request('POST','preview',['type'=>'wp-query','args'=>['post_type'=>'post']])->get_status()===403,'low privilege preview denied');
 get_role($role)->add_cap('manage_options');wp_set_current_user(0);wp_set_current_user($user);lfe_security_check(lfe_security_request('GET','content',['source'=>'wp-users'])->get_status()===403,'manage_options alone cannot inspect users');lfe_security_check(lfe_security_request('POST','preview',['type'=>'wp-users','args'=>['number'=>1]])->get_status()===403,'manage_options alone cannot preview users');
 wp_set_current_user($admin);foreach([['post_type'=>'post','unknown_sql'=>'DROP TABLE'],['post_type'=>'post','relationship'=>'bad'],['post_type'=>'post','relationship'=>['id'=>[]]],['post_type'=>'post','s'=>str_repeat('x',81000)],['post_type'=>'post','posts_per_page'=>[]]]as$args)lfe_security_check(lfe_security_request('POST','preview',['type'=>'wp-query','args'=>$args])->get_status()===400,'malformed or disallowed query rejected');
 lfe_security_check(lfe_security_request('GET','terms',['post_type'=>'post','taxonomy'=>'etch_collection'])->get_status()===400,'unassigned taxonomy lookup rejected');
 $response=lfe_security_request('POST','preview',['type'=>'wp-query','args'=>['post_type'=>'post','posts_per_page'=>-1],'sample'=>true]);lfe_security_check($response->get_status()===200&&count($response->get_data()['posts'])<=1,'authenticated preview bounded to one record');
 $old_cookie=$GLOBALS['wp_rest_auth_cookie']??null;$old_nonce=$_SERVER['HTTP_X_WP_NONCE']??null;$GLOBALS['wp_rest_auth_cookie']=true;$_SERVER['HTTP_X_WP_NONCE']='invalid';$nonce=rest_cookie_check_errors(null);lfe_security_check(is_wp_error($nonce)&&$nonce->get_error_code()==='rest_cookie_invalid_nonce','invalid REST cookie nonce rejected');$GLOBALS['wp_rest_auth_cookie']=$old_cookie;if($old_nonce===null)unset($_SERVER['HTTP_X_WP_NONCE']);else $_SERVER['HTTP_X_WP_NONCE']=$old_nonce;
}finally{wp_set_current_user($admin);if($user&&!is_wp_error($user)){if(!function_exists('wp_delete_user'))require_once ABSPATH.'wp-admin/includes/user.php';wp_delete_user($user);}remove_role($role);wp_set_current_user($old_user);echo 'Temporary security fixtures removed.'.PHP_EOL;}
